# Archive membership and every local source link are checked independently of report prose.
import tarfile
archive_checks=[]
for x in items:
    for path,needle in x['code']:
        if path.startswith('archive:') and needle:
            p=ROOT/path[8:]
            with tarfile.open(p) as t:
                matches=[m for m in t.getnames() if m.lstrip('./')==needle]
            assert matches,(path,needle)
            archive_checks.append({'id':x['id'],'archive':str(p),'member':needle,'exists':True})
(OUT/'archive_member_checks.json').write_text(json.dumps(archive_checks,ensure_ascii=False,indent=2)+'\n')
